(() => {
 const host=document.querySelector('.portfolio-wireframe');if(!host)return;
 const grid=host.querySelector('.portfolio-board');grid.className='client-board';grid.setAttribute('aria-label','Client projects');
 host.querySelector('.project-presentation')?.remove();host.querySelector('.board-caption span').textContent='SELECTED CLIENTS';host.querySelector('.board-intro').textContent='A selection of businesses and brands we have worked with.';
 const clients=[
 ['Cold Harbor','#173e39','cold-harbor'],['Natty','#d2242d','natty'],['The Den','#25201b','the-den'],['Cafe Owned By','#102b43','owned-by'],['Conway’s Landscaping','#426f39','conways'],['Bradley Landscaping','#334d32'],['Monson Self Storage','#4a5560'],['Eastern Security Safe','#354554'],['Shuflr','#38567a'],['Macy Lee','#c4222b'],['Alexis Rose Photography','#514445'],['Mackoul Electric','#344a59'],['Why Buy Rentals','#3f4c9c'],['Tree Wizard','#3a543d'],['Aqua Dreams','#387e96'],['Shlerk','#15182d'],['Mestek','#4d5a64'],['Dargie’s Vinyl Dreams','#52565c'],['Elite Tree & Snow','#536357'],['Lunch Ladies','#68625a'],['Italian Feast','#625b56'],['Richard Neal','#465261']
 ];
 const ratios=[16/9,1,3/4,1,3/2,2/3,1,4/3,16/9,1,3/4,1,3/2,1,2/3,4/3,16/9,3/4,1,1];
 let shown=0;const viewport=document.createElement('div');viewport.className='client-viewport';grid.before(viewport);viewport.append(grid);
 const wall=document.createElement('div');wall.className='board-blur-wall';const more=document.createElement('button');more.type='button';more.className='button board-load-more';more.textContent='Load more';wall.append(more);viewport.after(wall);
 const status=host.querySelector('.board-status');
 function render(){grid.replaceChildren();clients.slice(0,shown).forEach(([name,color,url],i)=>{const tile=document.createElement('button');tile.type='button';tile.className='client-tile';tile.style.backgroundColor=color;tile.style.aspectRatio=ratios[i%ratios.length];tile.addEventListener('click',()=>openDetail(i));const label=document.createElement('strong');label.textContent=name;tile.append(label);{const action=document.createElement('span');action.textContent='See more ↗';tile.append(action)}grid.append(tile)});wall.hidden=shown>=clients.length;status.textContent=`${shown} of ${clients.length} clients shown.`}

 let detail=null,returnFocus=null;
 const descriptions={'cold-harbor':'A coffee brand identity expressed across packaging, pattern and everyday objects.','natty':'A consumer wellness brand created by Bluechip’s founder, with identity and packaging artwork.','the-den':'A barber brand presented through identity and branded applications.','owned-by':'A café identity explored across packaging and promotional concepts.','conways':'A landscaping identity with logo and business card artwork.'};
 function openDetail(index){
  if(!detail){returnFocus=document.activeElement;detail=document.createElement('section');detail.className='client-detail';host.append(detail)}
  viewport.hidden=true;wall.hidden=true;host.querySelector('.board-caption').hidden=true;host.querySelector('.board-intro').hidden=true;host.querySelector('.board-footnote').hidden=true;const moreLink=host.querySelector('.portfolio-more');if(moreLink)moreLink.hidden=true;
  const [name,color,id]=clients[index],key='bluechip-detail-'+index;let state={liked:false,comments:[]};try{state={...state,...JSON.parse(localStorage.getItem(key)||'{}')}}catch{}
  detail.replaceChildren();const close=document.createElement('button');close.className='detail-close';close.textContent='←';close.setAttribute('aria-label','Back to projects');close.onclick=closeDetail;
  const panel=document.createElement('div');panel.className='detail-panel';const visual=document.createElement('div');visual.className='detail-visual';visual.style.background=color;const visualName=document.createElement('span');visualName.textContent=name;visual.append(close,visualName);
  const info=document.createElement('div');info.className='detail-info';const label=document.createElement('span');label.className='eyebrow';label.textContent='BLUECHIP PROJECT';const title=document.createElement('h3');title.textContent=name;const desc=document.createElement('p');desc.textContent=descriptions[id]||'A project from the Bluechip portfolio. More details are coming soon.';
  const like=document.createElement('button');like.className='detail-like';const syncLike=()=>{like.textContent=state.liked?'♥ 1 like':'♡ 0 likes';like.setAttribute('aria-pressed',String(state.liked))};const save=()=>{try{localStorage.setItem(key,JSON.stringify(state))}catch{}};syncLike();like.onclick=()=>{state.liked=!state.liked;save();syncLike()};
  const commentsTitle=document.createElement('h4');commentsTitle.textContent='Comments';const note=document.createElement('p');note.className='detail-note';note.textContent='Preview only: likes and comments are saved in this browser, not shared publicly.';const list=document.createElement('ul');list.className='detail-comments';function showComments(){list.replaceChildren();state.comments.forEach(c=>{const li=document.createElement('li');li.textContent=c;list.append(li)})}showComments();const form=document.createElement('form');form.className='detail-comment-form';const input=document.createElement('textarea');input.placeholder='Add a comment';input.setAttribute('aria-label','Add a comment');input.maxLength=500;input.required=true;const submit=document.createElement('button');submit.className='button';submit.textContent='Post comment';form.append(input,submit);form.onsubmit=e=>{e.preventDefault();const value=input.value.trim();if(!value)return;state.comments.push(value);save();showComments();input.value=''};
  const top=document.createElement('div');top.className='detail-top';top.append(like);const heading=document.createElement('div');heading.className='detail-heading';heading.append(label,title);const description=document.createElement('div');description.className='detail-description';const descriptionHeading=document.createElement('h4');descriptionHeading.textContent='Description';description.append(descriptionHeading,desc);info.append(top,heading);if(id){const link=document.createElement('a');link.href='/work/'+id;link.className='detail-project-link';link.textContent='View project';info.append(link)}info.append(description,commentsTitle,note,list,form);panel.append(visual,info);detail.append(panel);
  const relatedTitle=document.createElement('h3');relatedTitle.textContent='More from Bluechip';detail.append(relatedTitle);const related=document.createElement('div');related.className='detail-related';clients.map((c,i)=>({c,i})).filter(x=>x.i!==index).slice(0,4).forEach(({c,i})=>{const b=document.createElement('button');b.type='button';b.style.background=c[1];b.textContent=c[0];b.onclick=()=>openDetail(i);related.append(b)});detail.append(related);close.focus({preventScroll:true});detail.scrollIntoView({behavior:'smooth',block:'start'});
 }
 function closeDetail(){if(!detail)return;detail.remove();detail=null;viewport.hidden=false;host.querySelector('.board-caption').hidden=false;host.querySelector('.board-intro').hidden=false;host.querySelector('.board-footnote').hidden=false;const moreLink=host.querySelector('.portfolio-more');if(moreLink)moreLink.hidden=false;wall.hidden=shown>=clients.length;returnFocus?.focus({preventScroll:true})}
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&detail)closeDetail()});
 more.addEventListener('click',()=>{shown=Math.min(shown+4,clients.length);render()});shown=Math.min(16,clients.length);render();
})();
